package com.dao;import java.sql.*;import java.util.*;import com.entity.Appointment;public class AppointmentDao{private Connection c;public AppointmentDao(Connection c){this.c=c;}public boolean create(Appointment a){String q="INSERT INTO appointments(user_id,doctor_id,patient_name,gender,age,appointment_date,email,phone,disease,address,status) VALUES(?,?,?,?,?,?,?,?,?,?, 'PENDING')";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,a.userId);p.setInt(2,a.doctorId);p.setString(3,a.patientName);p.setString(4,a.gender);p.setInt(5,a.age);p.setString(6,a.appointmentDate);p.setString(7,a.email);p.setString(8,a.phone);p.setString(9,a.disease);p.setString(10,a.address);return p.executeUpdate()==1;}catch(Exception e){e.printStackTrace();return false;}}private List<Appointment> f(String q,int id){List<Appointment> a=new ArrayList<>();try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);ResultSet r=p.executeQuery();while(r.next()){Appointment x=new Appointment();x.id=r.getInt("id");x.userId=r.getInt("user_id");x.doctorId=r.getInt("doctor_id");x.patientName=r.getString("patient_name");x.gender=r.getString("gender");x.age=r.getInt("age");x.appointmentDate=r.getString("appointment_date");x.email=r.getString("email");x.phone=r.getString("phone");x.disease=r.getString("disease");x.address=r.getString("address");x.status=r.getString("status");a.add(x);}}catch(Exception e){e.printStackTrace();}return a;}public List<Appointment> byUser(int i){return f("SELECT * FROM appointments WHERE user_id=? ORDER BY appointment_date DESC",i);}public List<Appointment> byDoctor(int i){return f("SELECT * FROM appointments WHERE doctor_id=? ORDER BY appointment_date DESC",i);}public boolean status(int id,int d,String s){try(PreparedStatement p=c.prepareStatement("UPDATE appointments SET status=? WHERE id=? AND doctor_id=?")){p.setString(1,s);p.setInt(2,id);p.setInt(3,d);return p.executeUpdate()==1;}catch(Exception e){return false;}}}